--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: a_droit(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.a_droit(uid uuid, produit_demande text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from entitlement e
    where e.utilisateur_id = uid
      and (e.produit = produit_demande
           or (e.produit = 'pack_langues' and produit_demande like 'langue_%'))
      and e.debut_le <= now()
      and (e.fin_le is null or e.fin_le > now())
  );
$$;


ALTER FUNCTION public.a_droit(uid uuid, produit_demande text) OWNER TO postgres;

--
-- Name: composer_deck(text, public.difficulte_niveau, smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.composer_deck(p_categorie text, p_niveau public.difficulte_niveau, p_longueur smallint DEFAULT 7) RETURNS TABLE(question_id text, complete boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_bornes int[] := case p_niveau
                      when 'facile'    then array[1,2]
                      when 'moyen'     then array[3,3]
                      when 'difficile' then array[4,5]
                    end;
  v_dispo int;
begin
  if auth.uid() is null then
    raise exception 'Session requise pour composer un deck'
      using errcode = '28000';
  end if;

  if not niveau_debloque(p_categorie, p_niveau) then
    raise exception 'Niveau verrouillé : remporte deux parties au niveau précédent'
      using errcode = '42501';
  end if;

  select count(*) into v_dispo
  from question q
  where q.categorie = p_categorie
    and q.statut = 'valide'
    and q.type = 'qcm'
    and q.difficulte between v_bornes[1] and v_bornes[2];

  if v_dispo >= p_longueur then
    return query
      select q.id, false
      from question q
      where q.categorie = p_categorie
        and q.statut = 'valide'
        and q.type = 'qcm'
        and q.difficulte between v_bornes[1] and v_bornes[2]
      order by random()
      limit p_longueur;
  else
    return query
      select q.id, true
      from question q
      where q.categorie = p_categorie
        and q.statut = 'valide'
        and q.type = 'qcm'
      order by abs(q.difficulte - ((v_bornes[1] + v_bornes[2]) / 2.0)), random()
      limit p_longueur;
  end if;
end;
$$;


ALTER FUNCTION public.composer_deck(p_categorie text, p_niveau public.difficulte_niveau, p_longueur smallint) OWNER TO postgres;

--
-- Name: creer_profil(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.creer_profil() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into profil (id, anonyme)
  values (new.id, coalesce(new.is_anonymous, false))
  on conflict (id) do nothing;
  return new;
end;
$$;


ALTER FUNCTION public.creer_profil() OWNER TO postgres;

--
-- Name: defi_du_jour(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.defi_du_jour() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_categorie text;
  v_total int;
  v_fait boolean := false;
begin
  select count(*) into v_total from categorie_publique;
  if v_total = 0 then return null; end if;

  select categorie into v_categorie
  from (select categorie, row_number() over (order by categorie) - 1 as n
          from categorie_publique) t
  where n = (extract(doy from current_date)::int % v_total);

  if auth.uid() is not null then
    select exists (
      select 1 from partie
      where utilisateur_id = auth.uid()
        and mode = 'defi_du_jour'
        and statut = 'terminee'
        and terminee_le::date = current_date
    ) into v_fait;
  end if;

  return jsonb_build_object(
    'categorie', v_categorie, 'niveau', 'facile',
    'recompense_xp', 50, 'fait', v_fait);
end;
$$;


ALTER FUNCTION public.defi_du_jour() OWNER TO postgres;

--
-- Name: definir_pseudo(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.definir_pseudo(p_pseudo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pseudo text := trim(p_pseudo);
begin
  if auth.uid() is null then
    raise exception 'Session requise' using errcode = '28000';
  end if;
  if char_length(v_pseudo) < 2 or char_length(v_pseudo) > 24 then
    return jsonb_build_object('ok', false, 'motif', 'longueur');
  end if;
  if not pseudo_disponible(v_pseudo) then
    return jsonb_build_object('ok', false, 'motif', 'pris');
  end if;

  update profil set pseudo = v_pseudo where id = auth.uid();
  return jsonb_build_object('ok', true, 'pseudo', v_pseudo);
end;
$$;


ALTER FUNCTION public.definir_pseudo(p_pseudo text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: question; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.question (
    id text NOT NULL,
    type public.question_type DEFAULT 'qcm'::public.question_type NOT NULL,
    categorie text NOT NULL,
    sous_categorie text,
    enonce text NOT NULL,
    reponses jsonb NOT NULL,
    bonne_reponse smallint NOT NULL,
    explication text,
    source_url text,
    source_titre text,
    image_id text,
    image_alt text,
    difficulte smallint NOT NULL,
    statut public.question_statut DEFAULT 'brouillon'::public.question_statut NOT NULL,
    campagne_id uuid,
    langue text DEFAULT 'fr'::text NOT NULL,
    vues integer DEFAULT 0 NOT NULL,
    reussites integer DEFAULT 0 NOT NULL,
    publique boolean DEFAULT false NOT NULL,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    modifie_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT question_bonne_reponse_dans_bornes CHECK (((bonne_reponse >= 0) AND (bonne_reponse < jsonb_array_length(reponses)))),
    CONSTRAINT question_difficulte_check CHECK (((difficulte >= 1) AND (difficulte <= 5))),
    CONSTRAINT question_personnalite_sans_score CHECK (((type <> 'personnalite'::public.question_type) OR (campagne_id IS NOT NULL))),
    CONSTRAINT question_reponses_valides CHECK (((jsonb_array_length(reponses) >= 2) AND (jsonb_array_length(reponses) <= 6))),
    CONSTRAINT question_validee_est_sourcee CHECK (((statut <> 'valide'::public.question_statut) OR (source_url IS NOT NULL)))
);


ALTER TABLE public.question OWNER TO postgres;

--
-- Name: difficulte_observee(public.question); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.difficulte_observee(q public.question) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when q.vues >= 50 then round(q.reussites::numeric / q.vues, 3) end;
$$;


ALTER FUNCTION public.difficulte_observee(q public.question) OWNER TO postgres;

--
-- Name: etat_niveaux(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.etat_niveaux(p_categorie text) RETURNS TABLE(niveau public.difficulte_niveau, etoiles smallint, debloque boolean, condition text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    n.niveau,
    coalesce(m.etoiles, 0)::smallint,
    niveau_debloque(p_categorie, n.niveau),
    case n.niveau
      when 'facile'    then null
      when 'moyen'     then 'Remporte deux parties au niveau facile pour débloquer ce niveau.'
      when 'difficile' then 'Remporte deux parties au niveau moyen pour débloquer ce niveau.'
    end
  from (values ('facile'::difficulte_niveau), ('moyen'), ('difficile')) as n(niveau)
  left join maitrise m
    on m.utilisateur_id = auth.uid()
   and m.categorie = p_categorie
   and m.niveau = n.niveau
  order by array_position(array['facile','moyen','difficile']::difficulte_niveau[], n.niveau);
$$;


ALTER FUNCTION public.etat_niveaux(p_categorie text) OWNER TO postgres;

--
-- Name: evaluer_badges(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.evaluer_badges(p_uid uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_nouveaux text[] := '{}';
  v_avancements jsonb;
begin
  select jsonb_build_object(
    'premiere_victoire', (select count(*) from partie
                           where utilisateur_id = p_uid and statut = 'terminee'
                             and points >= 900 and bonnes >= 5),
    'serie_7',           (select serie_jours from profil where id = p_uid),
    'serie_30',          (select serie_jours from profil where id = p_uid),
    'incollable',        (select count(*) from partie
                           where utilisateur_id = p_uid and statut = 'terminee'
                             and bonnes = array_length(deck, 1)),
    'cent_bonnes',       (select coalesce(sum(bonnes), 0) from partie
                           where utilisateur_id = p_uid and statut = 'terminee'),
    'explorateur',       (select count(distinct categorie) from partie
                           where utilisateur_id = p_uid and statut = 'terminee'
                             and categorie is not null),
    'maitre_categorie',  (select coalesce(max(total), 0) from (
                            select sum(etoiles) as total from maitrise
                             where utilisateur_id = p_uid group by categorie) t),
    'veteran',           (select count(*) from partie
                           where utilisateur_id = p_uid and statut = 'terminee')
  ) into v_avancements;

  with maj as (
    insert into badge_obtenu (utilisateur_id, badge_id, avancement, obtenu_le)
    select
      p_uid,
      b.id,
      least((v_avancements ->> b.id)::int, b.objectif),
      case when (v_avancements ->> b.id)::int >= b.objectif then now() end
    from badge b
    where v_avancements ? b.id
    on conflict (utilisateur_id, badge_id) do update
      set avancement = greatest(badge_obtenu.avancement, excluded.avancement),
          -- obtenu_le ne se reecrit jamais : une serie qui retombe ne retire
          -- pas un badge deja gagne.
          obtenu_le  = coalesce(badge_obtenu.obtenu_le, excluded.obtenu_le)
    returning badge_id, obtenu_le, (xmax = 0) as cree
  )
  select coalesce(array_agg(badge_id), '{}')
    into v_nouveaux
  from maj
  where obtenu_le is not null
    and obtenu_le >= now() - interval '5 seconds';

  return v_nouveaux;
end;
$$;


ALTER FUNCTION public.evaluer_badges(p_uid uuid) OWNER TO postgres;

--
-- Name: exporter_mes_donnees(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exporter_mes_donnees() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'exporte_le', now(),
    'profil', (select to_jsonb(p) - 'id' from profil p where p.id = auth.uid()),
    'parties', (select coalesce(jsonb_agg(to_jsonb(x) - 'utilisateur_id' - 'adversaire_id'), '[]'::jsonb)
                  from partie x where x.utilisateur_id = auth.uid()),
    'reponses', (select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
                   from reponse r
                   join partie x on x.id = r.partie_id
                  where x.utilisateur_id = auth.uid()),
    'maitrise', (select coalesce(jsonb_agg(to_jsonb(m) - 'utilisateur_id'), '[]'::jsonb)
                   from maitrise m where m.utilisateur_id = auth.uid()),
    'badges', (select coalesce(jsonb_agg(to_jsonb(b) - 'utilisateur_id'), '[]'::jsonb)
                 from badge_obtenu b where b.utilisateur_id = auth.uid()),
    'droits', (select coalesce(jsonb_agg(to_jsonb(e) - 'utilisateur_id'), '[]'::jsonb)
                 from entitlement e where e.utilisateur_id = auth.uid()));
$$;


ALTER FUNCTION public.exporter_mes_donnees() OWNER TO postgres;

--
-- Name: maj_compteurs_question(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.maj_compteurs_question() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update question
     set vues      = vues + 1,
         reussites = reussites + case when new.correcte then 1 else 0 end
   where id = new.question_id;
  return new;
end;
$$;


ALTER FUNCTION public.maj_compteurs_question() OWNER TO postgres;

--
-- Name: nettoyer_comptes_anonymes(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nettoyer_comptes_anonymes(p_jours integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  v_supprimes integer;
begin
  with cibles as (
    select u.id
    from auth.users u
    join profil p on p.id = u.id
    where u.is_anonymous = true
      and coalesce(u.last_sign_in_at, u.created_at) < now() - make_interval(days => p_jours)
      -- Filet de securite : on ne supprime jamais quelqu'un qui a paye,
      -- meme anonyme, meme inactif.
      and not exists (select 1 from entitlement e where e.utilisateur_id = u.id)
  )
  delete from auth.users u using cibles c where u.id = c.id;

  get diagnostics v_supprimes = row_count;
  return v_supprimes;
end;
$$;


ALTER FUNCTION public.nettoyer_comptes_anonymes(p_jours integer) OWNER TO postgres;

--
-- Name: FUNCTION nettoyer_comptes_anonymes(p_jours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.nettoyer_comptes_anonymes(p_jours integer) IS 'Supprime les comptes anonymes inactifs depuis N jours, sauf ceux qui detiennent un droit paye. A planifier une fois par semaine.';


--
-- Name: niveau_debloque(text, public.difficulte_niveau, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.niveau_debloque(p_categorie text, p_niveau public.difficulte_niveau, p_uid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case p_niveau
    when 'facile' then true
    when 'moyen' then coalesce(
      (select etoiles >= 2 from maitrise
        where utilisateur_id = p_uid and categorie = p_categorie and niveau = 'facile'), false)
    when 'difficile' then coalesce(
      (select etoiles >= 2 from maitrise
        where utilisateur_id = p_uid and categorie = p_categorie and niveau = 'moyen'), false)
  end;
$$;


ALTER FUNCTION public.niveau_debloque(p_categorie text, p_niveau public.difficulte_niveau, p_uid uuid) OWNER TO postgres;

