    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    modifie_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT campagne_dates_coherentes CHECK (((date_fin IS NULL) OR (date_debut IS NULL) OR (date_fin > date_debut))),
    CONSTRAINT campagne_statut_check CHECK ((statut = ANY (ARRAY['brouillon'::text, 'programmee'::text, 'active'::text, 'archivee'::text]))),
    CONSTRAINT campagne_type_check CHECK ((type = ANY (ARRAY['quiz_thematique'::text, 'comparateur_civique'::text])))
);


ALTER TABLE public.campagne OWNER TO postgres;

--
-- Name: categorie_publique; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.categorie_publique WITH (security_invoker='false') AS
 SELECT categorie,
    (count(*))::integer AS nb_questions,
    (count(*) FILTER (WHERE ((difficulte >= 1) AND (difficulte <= 2))))::integer AS nb_facile,
    (count(*) FILTER (WHERE (difficulte = 3)))::integer AS nb_moyen,
    (count(*) FILTER (WHERE ((difficulte >= 4) AND (difficulte <= 5))))::integer AS nb_difficile
   FROM public.question
  WHERE ((statut = 'valide'::public.question_statut) AND (type = 'qcm'::public.question_type))
  GROUP BY categorie;


ALTER VIEW public.categorie_publique OWNER TO postgres;

--
-- Name: entitlement; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.entitlement (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    utilisateur_id uuid NOT NULL,
    produit text NOT NULL,
    debut_le timestamp with time zone DEFAULT now() NOT NULL,
    fin_le timestamp with time zone,
    source text DEFAULT 'stripe'::text NOT NULL,
    reference text,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entitlement_produit_check CHECK ((produit = ANY (ARRAY['plus'::text, 'langue_lingala'::text, 'pack_langues'::text])))
);


ALTER TABLE public.entitlement OWNER TO postgres;

--
-- Name: maitrise; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.maitrise (
    utilisateur_id uuid NOT NULL,
    categorie text NOT NULL,
    niveau public.difficulte_niveau NOT NULL,
    etoiles smallint DEFAULT 0 NOT NULL,
    CONSTRAINT maitrise_etoiles_check CHECK (((etoiles >= 0) AND (etoiles <= 2)))
);


ALTER TABLE public.maitrise OWNER TO postgres;

--
-- Name: partie; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partie (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    utilisateur_id uuid NOT NULL,
    adversaire_id uuid,
    mode public.partie_mode DEFAULT 'solo'::public.partie_mode NOT NULL,
    categorie text,
    niveau public.difficulte_niveau,
    quiz_special_id text,
    deck text[] NOT NULL,
    deck_complete boolean DEFAULT false NOT NULL,
    points integer DEFAULT 0 NOT NULL,
    bonnes smallint DEFAULT 0 NOT NULL,
    chrono_actif boolean DEFAULT true NOT NULL,
    statut public.partie_statut DEFAULT 'en_cours'::public.partie_statut NOT NULL,
    commencee_le timestamp with time zone DEFAULT now() NOT NULL,
    terminee_le timestamp with time zone,
    xp_gagne integer DEFAULT 0 NOT NULL,
    badges_gagnes text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT partie_deck_non_vide CHECK ((array_length(deck, 1) >= 1))
);


ALTER TABLE public.partie OWNER TO postgres;

--
-- Name: profil; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.profil (
    id uuid NOT NULL,
    pseudo text,
    anonyme boolean DEFAULT true NOT NULL,
    xp integer DEFAULT 0 NOT NULL,
    serie_jours integer DEFAULT 0 NOT NULL,
    serie_record integer DEFAULT 0 NOT NULL,
    derniere_partie_le date,
    chrono_actif boolean DEFAULT true NOT NULL,
    cree_le timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT profil_pseudo_check CHECK (((char_length(pseudo) >= 2) AND (char_length(pseudo) <= 24))),
    CONSTRAINT profil_serie_jours_check CHECK ((serie_jours >= 0)),
    CONSTRAINT profil_serie_record_check CHECK ((serie_record >= 0)),
    CONSTRAINT profil_xp_check CHECK ((xp >= 0))
);


ALTER TABLE public.profil OWNER TO postgres;

--
-- Name: question_publique; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.question_publique WITH (security_invoker='false') AS
 SELECT id,
    type,
    categorie,
    sous_categorie,
    enonce,
    reponses,
    image_id,
    image_alt,
    difficulte,
    langue,
    campagne_id
   FROM public.question
  WHERE (statut = 'valide'::public.question_statut);


ALTER VIEW public.question_publique OWNER TO postgres;

